WITH src AS (SELECT * FROM store_sales WHERE NOT (revenue > 3600 AND store_id IN (1, 2, 3, 5))), store_sales_stats AS (SELECT CASE WHEN units >= 37 THEN 'high' WHEN units >= 15 THEN 'mid' ELSE 'low' END AS units_bucket, COUNT(*) AS row_count, MAX(units) AS max_units FROM src GROUP BY CASE WHEN units >= 37 THEN 'high' WHEN units >= 15 THEN 'mid' ELSE 'low' END) SELECT units_bucket, row_count, max_units FROM store_sales_stats ORDER BY row_count;
